using LankaSaaS.Application;using LankaSaaS.Domain;using Microsoft.EntityFrameworkCore;
namespace LankaSaaS.Infrastructure;
public static class AccountingService
{
 static readonly (string Code,string Name,string Type)[] Defaults=[(SystemAccountCodes.Cash,"Cash and bank",AccountTypes.Asset),(SystemAccountCodes.Receivables,"Accounts receivable",AccountTypes.Asset),(SystemAccountCodes.Payables,"Accounts payable",AccountTypes.Liability),(SystemAccountCodes.EventRevenue,"Event revenue",AccountTypes.Revenue),(SystemAccountCodes.EventExpenses,"Event expenses",AccountTypes.Expense)];
 public static async Task EnsureAccounts(AppDbContext db,ITenantContext tenant,CancellationToken ct=default){var existing=await db.LedgerAccounts.Select(x=>x.Code).ToListAsync(ct);foreach(var x in Defaults.Where(x=>!existing.Contains(x.Code)))db.LedgerAccounts.Add(new LedgerAccount{TenantId=tenant.TenantId,Code=x.Code,Name=x.Name,Type=x.Type,IsSystem=true});if(db.ChangeTracker.HasChanges())await db.SaveChangesAsync(ct);}
 public static async Task Post(AppDbContext db,ITenantContext tenant,DateOnly date,string description,string sourceType,Guid sourceId,Guid? eventId,string? reference,(string Code,decimal Debit,decimal Credit)[] lines,CancellationToken ct=default){if(lines.Sum(x=>x.Debit)!=lines.Sum(x=>x.Credit)||lines.Sum(x=>x.Debit)<=0)throw new InvalidOperationException("Journal entry must balance.");if(await db.JournalEntries.AnyAsync(x=>x.SourceType==sourceType&&x.SourceId==sourceId,ct))return;await EnsureAccounts(db,tenant,ct);var codes=lines.Select(x=>x.Code).Distinct().ToList();var accounts=await db.LedgerAccounts.Where(x=>codes.Contains(x.Code)).ToDictionaryAsync(x=>x.Code,ct);var entry=new JournalEntry{TenantId=tenant.TenantId,EntryDate=date,Description=description,Reference=reference,EventId=eventId,SourceType=sourceType,SourceId=sourceId,Lines=lines.Select(x=>new JournalLine{TenantId=tenant.TenantId,AccountId=accounts[x.Code].Id,AccountCode=x.Code,AccountName=accounts[x.Code].Name,Debit=x.Debit,Credit=x.Credit}).ToList()};db.JournalEntries.Add(entry);}
}
